/* Source page shell (main) */
body:not(.wp-admin){background:var(--deep);}body:not(.wp-admin){background-color:black;}
/* Source page-level decor layers */
main.site-main{position:relative;}
main.site-main::before{content:"";position:absolute;pointer-events:none;background-image:radial-gradient(circle, oklch(0.65 0.25 45 / 0.18), rgba(0, 0, 0, 0) 60%);filter:blur(120px);z-index:-1;mix-blend-mode:screen;height:1620px;top:-270px;left:-576px;right:-576px;}
