.site-bg-video{top:45px !important;right:-144px !important;bottom:0px !important;left:504px !important;width:auto !important;height:auto !important;opacity:0.85 !important;filter:drop-shadow(oklch(0.65 0.25 45 / 0.3) 0px 0px 30px) !important;animation:tourbillon-float 24s cubic-bezier(0.25, 0.1, 0.25, 1) 0s infinite alternate none !important;}
@keyframes tourbillon-float { 0% { transform: translateY(0px) rotateZ(0deg) rotateX(2deg) rotateY(-3deg) scale(1); } 50% { transform: translateY(-20px) rotateZ(1deg) rotateX(-1deg) rotateY(1deg) scale(1.02); } 100% { transform: translateY(-40px) rotateZ(-1deg) rotateX(-2deg) rotateY(4deg) scale(1.04); } }
.site-bg-video video{transform:matrix(1.29505, -0.113302, 0.113302, 1.29505, 0, 0);filter:contrast(1.15) brightness(1.05);}

